window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f235a8fe987e2c22"]={"versions": [{"id": "FIG-f235a8fe987e2c22", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein UML-Klassendiagrammausschnitt aus der Spezifikation der AUTOSAR XML-Schema-Produktionsregeln (<code>AUTOSAR_TPS_XMLSchemaProductionRules</code>). Es illustriert die modellbasierte Konfiguration des Metamodells für die Generierung von W3C-XML-Schema-Definitionen (XSD). Konkret zeigt es die Anwendung eines UML-Stereotyp- bzw. Tagged-Value-Attributs zur Steuerung der XML-Schemagenerierung für die AUTOSAR-Wurzelklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die UML-Klasse <code>AUTOSAR</code>. Das Klassensymbol gliedert sich in ein oberes Namensabteil (<code>AUTOSAR</code>) und ein unteres Eigenschafts-/Attributabteil. Im unteren Abteil ist der Tagged Value <code>tags</code> mit der Definition <code>xml.globalElement = true</code> annotiert. Es sind keine weiteren Attribute, Operationen oder Assoziationen abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Fragment stellt die Abbildung keinen dynamischen Sequenz- oder Laufzeitablauf dar. Das Tag <code>xml.globalElement = true</code> steuert den statischen Schema-Generierungsprozess, indem es dem Schema-Generator vorgibt, für die Entität <code>AUTOSAR</code> ein globales XSD-Element (<code>&lt;xsd:element name=&quot;AUTOSAR&quot; .../&gt;</code>) auf der obersten Ebene des erzeugten XML-Schemas anzulegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Tool-Entwicklung im Rahmen des AUTOSAR-Metamodell- und XML-Schema-Exports ist die Eigenschaft <code>xml.globalElement</code> normativ verbindlich. Das Setzen auf <code>true</code> erzwingt die Deklaration eines korrespondierenden XML-Elements als direktes Kindelement des Wurzelelements <code>&lt;xsd:schema&gt;</code>. Dies ermöglicht die Verwendung des Elements als valides Dokumenten-Wurzelelement (Root-Element) in AUTOSAR-XML-Dateien (ARXML).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d1c61670c0d41da5", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein UML-Klassendiagrammausschnitt aus der Spezifikation der AUTOSAR XML-Schema-Produktionsregeln (<code>AUTOSAR_TPS_XMLSchemaProductionRules</code>). Es illustriert die modellbasierte Konfiguration des Metamodells für die Generierung von W3C-XML-Schema-Definitionen (XSD). Konkret zeigt es die Anwendung eines UML-Stereotyp- bzw. Tagged-Value-Attributs zur Steuerung der XML-Schemagenerierung für die AUTOSAR-Wurzelklasse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die UML-Klasse <code>AUTOSAR</code>. Das Klassensymbol gliedert sich in ein oberes Namensabteil (<code>AUTOSAR</code>) und ein unteres Eigenschafts-/Attributabteil. Im unteren Abteil ist der Tagged Value <code>tags</code> mit der Definition <code>xml.globalElement = true</code> annotiert. Es sind keine weiteren Attribute, Operationen oder Assoziationen abgebildet.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Fragment stellt die Abbildung keinen dynamischen Sequenz- oder Laufzeitablauf dar. Das Tag <code>xml.globalElement = true</code> steuert den statischen Schema-Generierungsprozess, indem es dem Schema-Generator vorgibt, für die Entität <code>AUTOSAR</code> ein globales XSD-Element (<code>&lt;xsd:element name=&quot;AUTOSAR&quot; .../&gt;</code>) auf der obersten Ebene des erzeugten XML-Schemas anzulegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Tool-Entwicklung im Rahmen des AUTOSAR-Metamodell- und XML-Schema-Exports ist die Eigenschaft <code>xml.globalElement</code> normativ verbindlich. Das Setzen auf <code>true</code> erzwingt die Deklaration eines korrespondierenden XML-Elements als direktes Kindelement des Wurzelelements <code>&lt;xsd:schema&gt;</code>. Dies ermöglicht die Verwendung des Elements als valides Dokumenten-Wurzelelement (Root-Element) in AUTOSAR-XML-Dateien (ARXML).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f235a8fe987e2c22", "to": "FIG-d1c61670c0d41da5", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
